// ===== CONFIG =====
const CONFIG = {
  waNumber: "6285768090238",
  storeName: "Gx Dikzz Store",
};

// ===== SOUND EFFECTS (base64 WAV embed) =====
const SFX_DATA = {
  click: "data:audio/wav;base64,",
  order: "data:audio/wav;base64,",
  addCart: "data:audio/wav;base64,",
  removeCart: "data:audio/wav;base64,",
  error: "data:audio/wav;base64,",
};

function sfx(type) {
  try {
    if (!SFX_DATA[type]) return;
    const audio = new Audio(SFX_DATA[type]);
    audio.volume = 0.55;
    audio.play().catch(() => {});
  } catch(e) {}
}

// ===== BACKSOUND =====
async function loadBacksound() {
  const audio = document.getElementById('backsound');
  const exts = ['mp3', 'ogg', 'wav', 'm4a'];
  for (const ext of exts) {
    try {
      const res = await fetch(`media/backsound.${ext}`, { method: 'HEAD' });
      if (res.ok) {
        audio.src = `media/backsound.${ext}`;
        audio.volume = 0.18;
        audio.loop = true;
        // Autoplay butuh interaksi user dulu di browser modern
        const tryPlay = () => {
          audio.play().catch(() => {});
          document.removeEventListener('click', tryPlay);
          document.removeEventListener('touchstart', tryPlay);
        };
        // Coba langsung, kalau gagal tunggu interaksi
        audio.play().catch(() => {
          document.addEventListener('click', tryPlay, { once: true });
          document.addEventListener('touchstart', tryPlay, { once: true });
        });
        break;
      }
    } catch(e) {}
  }
}

// ===== HERO BACKGROUND =====
async function loadHeroBg() {
  const hero = document.querySelector('.hero');
  const exts = ['jpg', 'jpeg', 'png', 'webp'];
  for (const ext of exts) {
    try {
      const res = await fetch(`media/bg.${ext}`, { method: 'HEAD' });
      if (res.ok) {
        hero.style.backgroundImage = `url('media/bg.${ext}')`;
        hero.style.backgroundSize = 'cover';
        hero.style.backgroundPosition = 'center';
        hero.style.backgroundRepeat = 'no-repeat';
        hero.classList.add('hero--has-bg');
        break;
      }
    } catch(e) {}
  }
}

// ===== SIDEBAR =====
function openSidebar() {
  document.getElementById('sidebar').classList.add('open');
  document.getElementById('sidebar-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeSidebar() {
  document.getElementById('sidebar').classList.remove('open');
  document.getElementById('sidebar-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== CART =====
const Cart = {
  get() { return JSON.parse(localStorage.getItem('gxdikzz_cart') || '[]'); },
  save(items) {
    localStorage.setItem('gxdikzz_cart', JSON.stringify(items));
    this.updateBadge();
  },
  add(product) {
    const items = this.get();
    const exists = items.find(i => i.nama === product.nama && i.pilihan === product.pilihan);
    if (!exists) {
      items.push(product);
      this.save(items);
      sfx('addCart');
      showToast('✅ Ditambahkan ke keranjang!');
    } else {
      sfx('error');
      showToast('⚠️ Produk sudah ada di keranjang!');
    }
  },
  remove(index) {
    sfx('removeCart');
    const items = this.get();
    items.splice(index, 1);
    this.save(items);
    renderCartModal();
  },
  updateBadge() {
    const count = this.get().length;
    const badge = document.getElementById('cart-badge');
    badge.textContent = count;
    badge.classList.toggle('show', count > 0);
  },
};

// Global wrapper for inline onclick
function removeCartItem(index) {
  Cart.remove(index);
}

// ===== PARSE TXT =====
function parseTxt(text) {
  const data = {};
  text.split('\n').forEach(line => {
    const idx = line.indexOf('=');
    if (idx > -1) {
      data[line.slice(0,idx).trim()] = line.slice(idx+1).trim();
    }
  });
  return data;
}

// ===== LOAD PRODUCTS =====
async function loadProducts() {
  const grid = document.getElementById('product-grid');
  const productFolders = [
    { folder: 'Bot Auto AI', icon: '🤖' },
    { folder: 'Panel Pterodactyl', icon: '📢' },
    { folder: 'Nokos', icon: '⚡' },
  ];
  const products = [];

  for (const item of productFolders) {
    try {
      const txtRes = await fetch(`media/produk/${item.folder}/${item.folder}.txt`);
      if (!txtRes.ok) continue;
      const txtData = parseTxt(await txtRes.text());

      let imgUrl = null;
      for (const ext of ['jpg','jpeg','png','webp','gif']) {
        const r = await fetch(`media/produk/${item.folder}/${item.folder}.${ext}`, { method: 'HEAD' });
        if (r.ok) { imgUrl = `media/produk/${item.folder}/${item.folder}.${ext}`; break; }
      }
      products.push({ ...txtData, imgUrl, icon: item.icon, folder: item.folder });
    } catch(e) { console.log(`Skip ${item.folder}:`, e); }
  }

  grid.innerHTML = '';
  if (products.length === 0) {
    grid.innerHTML = `<div class="loading-products">Tidak ada produk ditemukan.</div>`;
    return;
  }

  products.forEach((p, i) => {
    const card = document.createElement('div');
    card.className = 'product-card';
    card.style.animationDelay = `${i * 0.1}s`;

    const badgeClass = (p.badge || '').toLowerCase().replace(' ', '-');
    const imgHtml = p.imgUrl
      ? `<img class="product-img" src="${p.imgUrl}" alt="${p.nama}" loading="lazy">`
      : `<div class="product-img-placeholder">${p.icon}</div>`;

    const stokVal = (p.stok || 'Tersedia').trim();
    const isKosong = stokVal.toLowerCase() === 'kosong';
    const stokClass = isKosong ? 'stok-kosong' : 'stok-tersedia';
    const stokIcon = isKosong ? '❌' : '✅';

    card.innerHTML = `
      ${imgHtml}
      ${isKosong ? '<div class="card-kosong-banner">STOK HABIS</div>' : ''}
      <div class="product-body">
        <div class="product-top-row">
          <span class="product-badge ${badgeClass}">${p.badge || 'Produk'}</span>
          <span class="product-stok ${stokClass}">${stokIcon} ${stokVal}</span>
        </div>
        <div class="product-name">${p.nama}</div>
        <div class="product-desc">${p.deskripsi}</div>
        <div class="product-price">${p.harga}</div>
      </div>`;

    card.addEventListener('click', () => { sfx('click'); openProductModal(p); });
    grid.appendChild(card);
  });
}

// ===== SELECTED PILIHAN STATE =====
let _selectedPilihan = null;
let _currentProduct = null;

// ===== PRODUCT MODAL =====
function openProductModal(p) {
  _selectedPilihan = null;
  _currentProduct = p;

  const modal = document.getElementById('modal-product');
  const overlay = document.getElementById('overlay-product');

  const stokVal = (p.stok || 'Tersedia').trim();
  const isKosong = stokVal.toLowerCase() === 'kosong';
  const stokClass = isKosong ? 'stok-kosong' : 'stok-tersedia';
  const stokIcon = isKosong ? '❌' : '✅';
  const badgeClass = (p.badge || '').toLowerCase().replace(' ', '-');

  const imgHtml = p.imgUrl
    ? `<img class="modal-img" src="${p.imgUrl}" alt="${p.nama}">`
    : `<div class="modal-img-placeholder">${p.icon}</div>`;

  const fiturHtml = p.fitur
    ? `<div class="modal-features">
        <h4>Fitur Unggulan</h4>
        <ul class="feature-list">
          ${p.fitur.split('|').map(f => `<li>${f.trim()}</li>`).join('')}
        </ul>
      </div>` : '';

  let pilihanHtml = '';
  if (p.pilihan && !isKosong) {
    const opts = p.pilihan.split('|').map(s => s.trim());
    _selectedPilihan = opts[0];
    pilihanHtml = `
      <div class="modal-pilihan">
        <div class="pilihan-label">PILIH PAKET:</div>
        <div class="pilihan-list" id="pilihan-list">
          ${opts.map((opt, idx) => `
            <div class="pilihan-item ${idx===0?'selected':''}" data-value="${opt}" onclick="sfx('click'); selectPilihan(this,'${opt.replace(/'/g,"\\'")}')">
              <span class="pilihan-radio ${idx===0?'checked':''}"></span>
              <span class="pilihan-text">${opt}</span>
            </div>`).join('')}
        </div>
      </div>`;
  }

  // Tombol action — disabled kalau kosong
  const actionHtml = isKosong
    ? `<div class="modal-actions">
        <button class="btn-secondary btn-disabled" onclick="sfx('error'); showKosongPopup()">🛒 Keranjang</button>
        <button class="btn-primary btn-disabled" onclick="sfx('error'); showKosongPopup()">💬 Order WA</button>
       </div>`
    : `<div class="modal-actions">
        <button class="btn-secondary" onclick="addToCartWithPilihan()">🛒 Keranjang</button>
        <button class="btn-primary" onclick="sfx('order'); orderWAWithPilihan('${p.nama.replace(/'/g,"\\'")}')">💬 Order WA</button>
       </div>`;

  modal.innerHTML = `
    ${imgHtml}
    <div class="modal-body">
      <div class="modal-top-row">
        <span class="product-badge ${badgeClass}">${p.badge || 'Produk'}</span>
        <button class="modal-close" onclick="sfx('click'); closeModal('overlay-product')">✕</button>
      </div>
      <div class="modal-name">${p.nama}</div>
      <div class="modal-stok-row"><span class="product-stok ${stokClass}">${stokIcon} ${stokVal}</span></div>
      <div class="modal-price">${p.harga}</div>
      <div class="modal-desc">${p.deskripsi}</div>
      ${fiturHtml}
      ${pilihanHtml}
      ${actionHtml}
    </div>`;

  overlay.classList.add('open');
}

function showKosongPopup() {
  closeModal('overlay-product');
  setTimeout(() => {
    document.getElementById('overlay-stok-kosong').classList.add('open');
  }, 200);
}

function selectPilihan(el, val) {
  _selectedPilihan = val;
  document.querySelectorAll('.pilihan-item').forEach(i => {
    i.classList.remove('selected');
    i.querySelector('.pilihan-radio').classList.remove('checked');
  });
  el.classList.add('selected');
  el.querySelector('.pilihan-radio').classList.add('checked');
}

function addToCartWithPilihan() {
  if (!_currentProduct) return;
  if (!_selectedPilihan) { sfx('error'); showToast('⚠️ Pilih paket dulu!'); return; }
  const nama = _currentProduct.nama;
  const harga = _selectedPilihan.includes(':') ? _selectedPilihan.split(':').slice(1).join(':').trim() : _selectedPilihan;
  const imgUrl = _currentProduct.imgUrl || null;
  const icon = _currentProduct.icon || '📦';
  sfx('addCart');
  Cart.add({ nama, harga, imgUrl, icon, pilihan: _selectedPilihan });
}

function orderWAWithPilihan() {
  if (!_currentProduct) return;
  if (!_selectedPilihan) { sfx('error'); showToast('⚠️ Pilih paket dulu!'); return; }
  const nama = _currentProduct.nama;
  const msg = encodeURIComponent(`Bang, saya mau beli produk berikut ini:\n\n📦 *${nama}*\n📌 *Pilihan:* ${_selectedPilihan}`);
  window.open(`https://wa.me/${CONFIG.waNumber}?text=${msg}`, '_blank');
}

// ===== CART MODAL =====
function openCartModal() {
  renderCartModal();
  document.getElementById('overlay-cart').classList.add('open');
}

function renderCartModal() {
  const modal = document.getElementById('modal-cart');
  const items = Cart.get();

  if (items.length === 0) {
    modal.querySelector('.cart-items').innerHTML = `
      <div class="cart-empty">
        <div class="cart-empty-icon">🛒</div>
        <div>Keranjang masih kosong</div>
      </div>`;
    modal.querySelector('.cart-footer').innerHTML = '';
    return;
  }

  modal.querySelector('.cart-items').innerHTML = items.map((item, idx) => {
    // Gambar: pakai imgUrl produk kalau ada, fallback icon emoji
    const imgHtml = item.imgUrl
      ? `<img src="${item.imgUrl}" alt="${item.nama}" class="cart-item-img" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex'">`
      : '';
    const iconHtml = `<div class="cart-item-icon" style="${item.imgUrl ? 'display:none' : ''}">${item.icon || '📦'}</div>`;
    return `
    <div class="cart-item">
      <div class="cart-item-thumb">
        ${imgHtml}
        ${iconHtml}
      </div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.nama}</div>
        ${item.pilihan ? `<div class="cart-item-pilihan">📌 ${item.pilihan}</div>` : ''}
        <div class="cart-item-price">${item.harga}</div>
      </div>
      <button class="btn-remove" onclick="removeCartItem(${idx})">🗑️</button>
    </div>`;
  }).join('');

  modal.querySelector('.cart-footer').innerHTML = `
    <div class="cart-total">
      <span class="cart-total-label">${items.length} produk dipilih</span>
    </div>
    <div class="modal-actions" style="margin-top:16px">
      <button class="btn-secondary" onclick="sfx('click'); closeModal('overlay-cart')">Tutup</button>
      <button class="btn-primary" onclick="sfx('order'); orderWACart()">💬 Order Semua</button>
    </div>`;
}

// ===== ORDER WA CART =====
function orderWACart() {
  const items = Cart.get();
  const msgLines = items.map(i => `📦 *${i.nama}*\n📌 *Pilihan:* ${i.pilihan || '-'}`).join('\n\n');
  const msg = encodeURIComponent(`Bang, saya mau beli produk berikut ini:\n\n${msgLines}`);
  window.open(`https://wa.me/${CONFIG.waNumber}?text=${msg}`, '_blank');
}

// ===== MODAL CLOSE =====
function closeModal(overlayId) {
  document.getElementById(overlayId).classList.remove('open');
}

// ===== TOAST =====
function showToast(msg) {
  const toast = document.getElementById('toast');
  toast.textContent = msg;
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 2500);
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  loadHeroBg();
  loadBacksound();
  loadProducts();
  Cart.updateBadge();

  document.querySelectorAll('.modal-overlay').forEach(overlay => {
    overlay.addEventListener('click', e => {
      if (e.target === overlay) overlay.classList.remove('open');
    });
  });

  document.addEventListener('keydown', e => {
    if (e.key === 'Escape') closeSidebar();
  });
});
